import gcopyWithin = require( './index' );


// TESTS //

// The function returns a collection...
{
	const x = new Float64Array( 10 );

	gcopyWithin( x.length, 3, 1, 4, x, 1 ); // $ExpectType Collection<number>
}

// The compiler throws an error if the function is provided a first argument which is not a number...
{
	const x = new Float64Array( 10 );

	gcopyWithin( '3', 3, 1, 2, x, 1 ); // $ExpectError
	gcopyWithin( true, 3, 1, 2, x, 1 ); // $ExpectError
	gcopyWithin( false, 3, 1, 2, x, 1 ); // $ExpectError
	gcopyWithin( null, 3, 1, 2, x, 1 ); // $ExpectError
	gcopyWithin( undefined, 3, 1, 2, x, 1 ); // $ExpectError
	gcopyWithin( [], 3, 1, 2, x, 1 ); // $ExpectError
	gcopyWithin( {}, 3, 1, 2, x, 1 ); // $ExpectError
	gcopyWithin( ( x: number ): number => x, 3, 1, 2, x, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a number...
{
	const x = new Float64Array( 10 );

	gcopyWithin( x.length, '3', 1, 2, x, 1 ); // $ExpectError
	gcopyWithin( x.length, true, 1, 2, x, 1 ); // $ExpectError
	gcopyWithin( x.length, false, 1, 2, x, 1 ); // $ExpectError
	gcopyWithin( x.length, null, 1, 2, x, 1 ); // $ExpectError
	gcopyWithin( x.length, undefined, 1, 2, x, 1 ); // $ExpectError
	gcopyWithin( x.length, [], 1, 2, x, 1 ); // $ExpectError
	gcopyWithin( x.length, {}, 1, 2, x, 1 ); // $ExpectError
	gcopyWithin( x.length, ( x: number ): number => x, 1, 2, x, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a third argument which is not a number...
{
	const x = new Float64Array( 10 );

	gcopyWithin( x.length, 3, '1', 2, x, 1 ); // $ExpectError
	gcopyWithin( x.length, 3, true, 2, x, 1 ); // $ExpectError
	gcopyWithin( x.length, 3, false, 2, x, 1 ); // $ExpectError
	gcopyWithin( x.length, 3, null, 2, x, 1 ); // $ExpectError
	gcopyWithin( x.length, 3, undefined, 2, x, 1 ); // $ExpectError
	gcopyWithin( x.length, 3, [], 2, x, 1 ); // $ExpectError
	gcopyWithin( x.length, 3, {}, 2, x, 1 ); // $ExpectError
	gcopyWithin( x.length, 3, ( x: number ): number => x, 2, x, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a fourth argument which is not a number...
{
	const x = new Float64Array( 10 );

	gcopyWithin( x.length, 3, 1, '2', x, 1 ); // $ExpectError
	gcopyWithin( x.length, 3, 1, true, x, 1 ); // $ExpectError
	gcopyWithin( x.length, 3, 1, false, x, 1 ); // $ExpectError
	gcopyWithin( x.length, 3, 1, null, x, 1 ); // $ExpectError
	gcopyWithin( x.length, 3, 1, undefined, x, 1 ); // $ExpectError
	gcopyWithin( x.length, 3, 1, [], x, 1 ); // $ExpectError
	gcopyWithin( x.length, 3, 1, {}, x, 1 ); // $ExpectError
	gcopyWithin( x.length, 3, 1, ( x: number ): number => x, x, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a fifth argument which is not a collection...
{
	const x = new Float64Array( 10 );

	gcopyWithin( x.length, 3, 1, 2, 10, 1 ); // $ExpectError
	gcopyWithin( x.length, 3, 1, 2, true, 1 ); // $ExpectError
	gcopyWithin( x.length, 3, 1, 2, false, 1 ); // $ExpectError
	gcopyWithin( x.length, 3, 1, 2, null, 1 ); // $ExpectError
	gcopyWithin( x.length, 3, 1, 2, undefined, 1 ); // $ExpectError
	gcopyWithin( x.length, 3, 1, 2, {}, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a sixth argument which is not a number...
{
	const x = new Float64Array( 10 );

	gcopyWithin( x.length, 3, 1, 2, x, '4' ); // $ExpectError
	gcopyWithin( x.length, 3, 1, 2, x, true ); // $ExpectError
	gcopyWithin( x.length, 3, 1, 2, x, false ); // $ExpectError
	gcopyWithin( x.length, 3, 1, 2, x, null ); // $ExpectError
	gcopyWithin( x.length, 3, 1, 2, x, undefined ); // $ExpectError
	gcopyWithin( x.length, 3, 1, 2, x, [] ); // $ExpectError
	gcopyWithin( x.length, 3, 1, 2, x, {} ); // $ExpectError
	gcopyWithin( x.length, 3, 1, 2, x, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided insufficient arguments...
{
	const x = new Float64Array( 10 );

	gcopyWithin(); // $ExpectError
	gcopyWithin( x.length ); // $ExpectError
	gcopyWithin( x.length, 3 ); // $ExpectError
	gcopyWithin( x.length, 3, 1 ); // $ExpectError
	gcopyWithin( x.length, 3, 1, 2 ); // $ExpectError
	gcopyWithin( x.length, 3, 1, 2, x ); // $ExpectError
	gcopyWithin( x.length, 3, 1, 2, x, 1, {} ); // $ExpectError
}

// Attached to main export is an `ndarray` method which returns a collection...
{
	const x = new Float64Array( 10 );

	gcopyWithin.ndarray( x.length, 3, 1, 4, x, 1, 0 ); // $ExpectType Collection<number>
}

// The compiler throws an error if the `ndarray` method is provided a first argument which is not a number...
{
	const x = new Float64Array( 10 );

	gcopyWithin.ndarray( '2', 3, 1, 2, x, 1, 0 ); // $ExpectError
	gcopyWithin.ndarray( true, 3, 1, 2, x, 1, 0 ); // $ExpectError
	gcopyWithin.ndarray( false, 3, 1, 2, x, 1, 0 ); // $ExpectError
	gcopyWithin.ndarray( null, 3, 1, 2, x, 1, 0 ); // $ExpectError
	gcopyWithin.ndarray( undefined, 3, 1, 2, x, 1, 0 ); // $ExpectError
	gcopyWithin.ndarray( [], 2, 1, 2, x, 1, 0 ); // $ExpectError
	gcopyWithin.ndarray( {}, 2, 1, 2, x, 1, 0 ); // $ExpectError
	gcopyWithin.ndarray( ( x: number ): number => x, 2, 1, 2, x, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a fifth argument which is not a collection...
{
	const x = new Float64Array( 10 );

	gcopyWithin.ndarray( x.length, 3, 1, 2, 10, 1, 0 ); // $ExpectError
	gcopyWithin.ndarray( x.length, 3, 1, 2, true, 1, 0 ); // $ExpectError
	gcopyWithin.ndarray( x.length, 3, 1, 2, false, 1, 0 ); // $ExpectError
	gcopyWithin.ndarray( x.length, 3, 1, 2, null, 1, 0 ); // $ExpectError
	gcopyWithin.ndarray( x.length, 3, 1, 2, undefined, 1, 0 ); // $ExpectError
	gcopyWithin.ndarray( x.length, 3, 1, 2, {}, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided insufficient arguments...
{
	const x = new Float64Array( 10 );

	gcopyWithin.ndarray(); // $ExpectError
	gcopyWithin.ndarray( x.length ); // $ExpectError
	gcopyWithin.ndarray( x.length, 3 ); // $ExpectError
	gcopyWithin.ndarray( x.length, 3, 1 ); // $ExpectError
	gcopyWithin.ndarray( x.length, 3, 1, 2 ); // $ExpectError
	gcopyWithin.ndarray( x.length, 3, 1, 2, x ); // $ExpectError
	gcopyWithin.ndarray( x.length, 3, 1, 2, x, 1 ); // $ExpectError
	gcopyWithin.ndarray( x.length, 3, 1, 2, x, 1, 0, {} ); // $ExpectError
}
